using System.Windows;using System.Windows.Controls;using DirectorFamilyTravelDesk.Models;namespace DirectorFamilyTravelDesk.Views;public partial class RoutesView:UserControl,IRefreshable{private long _id;public RoutesView(){InitializeComponent();}public void RefreshData(){var c=App.Repository.GetCities(false);FromCity.ItemsSource=c;ToCity.ItemsSource=c;Grid.ItemsSource=App.Repository.GetRoutes(false);}private void Grid_SelectionChanged(object s,SelectionChangedEventArgs e){if(Grid.SelectedItem is RouteItem x){_id=x.Id;FromCity.SelectedValue=x.FromCityId;ToCity.SelectedValue=x.ToCityId;ActiveBox.IsChecked=x.IsActive;}}private void Save_Click(object s,RoutedEventArgs e){if(FromCity.SelectedValue is not long f||ToCity.SelectedValue is not long t||f==t){MessageBox.Show("Select different From and To cities.");return;}try{App.Repository.SaveRoute(new(){Id=_id,FromCityId=f,ToCityId=t,IsActive=ActiveBox.IsChecked==true});_id=0;FromCity.SelectedIndex=ToCity.SelectedIndex=-1;ActiveBox.IsChecked=true;RefreshData();}catch(Exception ex){MessageBox.Show(ex.Message);}}}